CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY);
CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE carriers (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL);
CREATE TABLE users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL);
CREATE TABLE drivers (id uuid PRIMARY KEY, carrier_id uuid NOT NULL REFERENCES carriers, name text NOT NULL, UNIQUE(id,carrier_id));
CREATE TABLE memberships (user_id uuid REFERENCES users, carrier_id uuid REFERENCES carriers, role text NOT NULL CHECK(role IN ('dispatcher','carrier-manager','driver')), driver_id uuid REFERENCES drivers, PRIMARY KEY(user_id,carrier_id), CHECK((role='driver')=(driver_id IS NOT NULL)), FOREIGN KEY(driver_id,carrier_id) REFERENCES drivers(id,carrier_id));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE carrier_dispatch_authorizations (id uuid PRIMARY KEY, carrier_id uuid NOT NULL REFERENCES carriers, agreement_ref text NOT NULL, verified_at timestamptz NOT NULL, effective_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, CHECK(expires_at>effective_at));
CREATE TABLE vehicles (id uuid PRIMARY KEY, carrier_id uuid NOT NULL REFERENCES carriers, label text NOT NULL, UNIQUE(id,carrier_id));
CREATE TABLE loads (id uuid PRIMARY KEY, carrier_id uuid NOT NULL REFERENCES carriers, reference text NOT NULL, source text NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>=0 AND amount_minor<=9007199254740991), currency text NOT NULL DEFAULT 'USD' CHECK(currency='USD'), stage text NOT NULL DEFAULT 'booked' CHECK(stage IN ('booked','dispatched','picked-up','delivered')), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(carrier_id,reference), UNIQUE(id,carrier_id));
CREATE TABLE load_stops (id uuid PRIMARY KEY, load_id uuid NOT NULL REFERENCES loads, sequence integer NOT NULL CHECK(sequence>0), kind text NOT NULL CHECK(kind IN ('pickup','delivery')), address text NOT NULL, timezone text NOT NULL, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, CHECK(window_end>=window_start), UNIQUE(load_id,sequence));
CREATE TABLE load_assignments (load_id uuid PRIMARY KEY, carrier_id uuid NOT NULL, driver_id uuid NOT NULL, vehicle_id uuid, FOREIGN KEY(load_id,carrier_id) REFERENCES loads(id,carrier_id), FOREIGN KEY(driver_id,carrier_id) REFERENCES drivers(id,carrier_id), FOREIGN KEY(vehicle_id,carrier_id) REFERENCES vehicles(id,carrier_id));
CREATE TABLE load_events (id uuid PRIMARY KEY, load_id uuid NOT NULL REFERENCES loads, carrier_id uuid NOT NULL REFERENCES carriers, actor_id uuid NOT NULL REFERENCES users, type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES load_events, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, delivered_at timestamptz);
CREATE TABLE audit_logs (id uuid PRIMARY KEY, actor_id uuid REFERENCES users, action text NOT NULL, resource_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys (user_id uuid REFERENCES users, key text NOT NULL, request_hash text NOT NULL, load_id uuid REFERENCES loads, PRIMARY KEY(user_id,key));
CREATE INDEX load_queue ON loads(carrier_id,stage,created_at DESC);
CREATE INDEX event_timeline ON load_events(load_id,created_at);
CREATE FUNCTION immutable_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only record'; END $$;
CREATE TRIGGER immutable_load_events BEFORE UPDATE OR DELETE ON load_events FOR EACH ROW EXECUTE FUNCTION immutable_event();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_event();
